#!/usr/bin/env Rscript

# Truth-based FACS benchmark generated by Crispulator.jl 0.5.1.
#
# The primary comparison asks whether adding an unsorted 0--100% bulk sample
# to the low and high 25% tails improves recovery. Bulk overlaps both tails,
# so it is not an independent third FACS bin. Bulk and input are independent
# sequencing draws from the same cell frequencies, making their contrast a
# deliberate null reference.

options(stringsAsFactors = FALSE)
source(file.path("R", "method_palette.R"))

data_dir <- Sys.getenv(
  "CRISPULATOR_DATA_DIR",
  file.path("data", "derived", "crispulator_facs")
)
result_dir <- Sys.getenv(
  "CRISPULATOR_RESULT_DIR",
  file.path("results", "crispulator_facs")
)
figure_path <- Sys.getenv(
  "CRISPULATOR_FIGURE_PATH",
  file.path("figures", "crispulator_facs_benchmark.pdf")
)
dir.create(result_dir, recursive = TRUE, showWarnings = FALSE)
dir.create(dirname(figure_path), recursive = TRUE, showWarnings = FALSE)

required <- file.path(
  data_dir,
  c("counts.tsv", "sample_design.tsv", "guide_truth.tsv", "gene_truth.tsv")
)
if (!all(file.exists(required))) {
  stop(
    "Run `julia --project=julia julia/simulate_crispulator_facs.jl` first.",
    call. = FALSE
  )
}

count_table <- read.delim(required[1L], check.names = FALSE)
sample_data <- read.delim(required[2L], check.names = FALSE)
guide_truth <- read.delim(required[3L], check.names = FALSE)
gene_truth <- read.delim(required[4L], check.names = FALSE)
gene_truth$active <- tolower(as.character(gene_truth$active)) == "true"
counts <- as.matrix(count_table[, sample_data$sample, drop = FALSE])
storage.mode(counts) <- "double"
stopifnot(
  identical(count_table$guide, guide_truth$guide),
  identical(count_table$gene, guide_truth$gene),
  all(colSums(counts) > 0),
  all(table(sample_data$replicate) == 4L)
)

# Load the RcppArmadillo weighted-crossproduct kernels when available.
cpp_library <- file.path("CB2", "src", paste0("CB2", .Platform$dynlib.ext))
if (file.exists(cpp_library) &&
    requireNamespace("Rcpp", quietly = TRUE) &&
    requireNamespace("RcppArmadillo", quietly = TRUE)) {
  suppressPackageStartupMessages(library(Rcpp))
  suppressPackageStartupMessages(library(RcppArmadillo))
  if (!"CB2" %in% names(getLoadedDLLs())) {
    dyn.load(cpp_library)
  }
  source(file.path("CB2", "R", "RcppExports.R"))
}
source(file.path("R", "bbreg.R"))

conditional_normal_mean <- function(lower, upper) {
  mass <- pnorm(upper) - pnorm(lower)
  (dnorm(lower) - dnorm(upper)) / mass
}
q25 <- qnorm(0.25)
sample_data$phenotype_z <- NA_real_
sample_data$phenotype_z[sample_data$sample_type == "low"] <-
  conditional_normal_mean(-Inf, q25)
sample_data$phenotype_z[sample_data$sample_type == "high"] <-
  conditional_normal_mean(-q25, Inf)
sample_data$phenotype_z[sample_data$sample_type == "bulk"] <- 0
sample_data$replicate <- factor(sample_data$replicate)

combine_guides <- function(guide_result) {
  groups <- split(seq_len(nrow(guide_result)), guide_result$gene)
  result <- do.call(rbind, lapply(names(groups), function(gene_name) {
    index <- groups[[gene_name]]
    valid <- is.finite(guide_result$estimate[index]) &
      is.finite(guide_result$p_value[index])
    index <- index[valid]
    if (!length(index)) {
      return(NULL)
    }
    signed_z <- sign(guide_result$estimate[index]) *
      qnorm(
        pmax(guide_result$p_value[index] / 2, .Machine$double.xmin),
        lower.tail = FALSE
      )
    combined_z <- sum(signed_z) / sqrt(length(signed_z))
    data.frame(
      gene = gene_name,
      n_guides = length(index),
      estimate = median(guide_result$estimate[index]),
      p_value = 2 * pnorm(-abs(combined_z)),
      converged_fraction = mean(guide_result$converged[index])
    )
  }))
  result$fdr <- p.adjust(result$p_value, method = "BH")
  rownames(result) <- NULL
  result
}

run_barcs <- function(label, sample_index, term = "phenotype_z") {
  design <- droplevels(sample_data[sample_index, , drop = FALSE])
  count_subset <- counts[, sample_index, drop = FALSE]
  formula <- if (term == "phenotype_z") {
    ~ phenotype_z + replicate
  } else {
    ~ bulk_indicator + replicate
  }
  if (term == "bulk_indicator") {
    design$bulk_indicator <- as.integer(design$sample_type == "bulk")
  }
  start <- proc.time()
  guide_result <- bb_screen(
    counts = count_subset,
    totals = colSums(count_subset),
    data = design,
    formula = formula,
    term = term,
    guide = guide_truth$guide,
    gene = guide_truth$gene,
    min_total_count = 30,
    ncores = 4
  )
  elapsed <- unname((proc.time() - start)[["elapsed"]])
  calibrated <- bb_calibrate_controls(
    guide_result,
    guide_truth$class == "negcontrol",
    alpha = 0.05
  )
  gene_result <- combine_guides(calibrated)
  write.csv(
    calibrated,
    gzfile(file.path(result_dir, paste0(label, "_guide_results.csv.gz"))),
    row.names = FALSE
  )
  write.csv(
    gene_result,
    file.path(result_dir, paste0(label, "_gene_results.csv")),
    row.names = FALSE
  )
  write.csv(
    data.frame(
      method = label,
      elapsed_seconds = elapsed,
      guides_per_second = nrow(guide_result) / elapsed,
      converged_fraction = mean(guide_result$converged),
      control_scale = attr(calibrated, "control_scale")
    ),
    file.path(result_dir, paste0(label, "_runtime.csv")),
    row.names = FALSE
  )
  gene_result
}

three_sample_index <- sample_data$sample_type %in% c("low", "bulk", "high")
tail_index <- sample_data$sample_type %in% c("low", "high")
bulk_index <- sample_data$sample_type %in% c("input", "bulk")

barcs_three <- run_barcs("barcs_low_bulk_high", three_sample_index)
barcs_tails <- run_barcs("barcs_two_tails", tail_index)
barcs_bulk <- run_barcs(
  "barcs_bulk_vs_input", bulk_index, term = "bulk_indicator"
)

mageck <- file.path(".venv", "bin", "mageck")
if (!file.exists(mageck)) {
  stop("Official MAGeCK 0.5.9.5 is required at `.venv/bin/mageck`.")
}
mageck_environment <- paste0(
  "PATH=", normalizePath(dirname(mageck)), ":", Sys.getenv("PATH")
)

run_mageck_mle <- function(label, sample_index) {
  design_data <- droplevels(sample_data[sample_index, , drop = FALSE])
  count_subset <- counts[, sample_index, drop = FALSE]
  score_range <- diff(range(design_data$phenotype_z))
  score_unit <- (
    design_data$phenotype_z - min(design_data$phenotype_z)
  ) / score_range

  count_path <- file.path(result_dir, paste0(label, "_counts.tsv"))
  design_path <- file.path(result_dir, paste0(label, "_design.tsv"))
  prefix <- file.path(result_dir, label)
  summary_path <- paste0(prefix, ".gene_summary.txt")
  write.table(
    data.frame(
      sgRNA = guide_truth$guide,
      Gene = guide_truth$gene,
      count_subset,
      check.names = FALSE
    ),
    count_path,
    sep = "\t", quote = FALSE, row.names = FALSE
  )
  replicate_matrix <- model.matrix(
    ~ replicate, data = design_data
  )[, -1L, drop = FALSE]
  mageck_design <- data.frame(
    samples = design_data$sample,
    baseline = 1,
    phenotype = score_unit,
    replicate_matrix,
    check.names = FALSE
  )
  write.table(
    mageck_design,
    design_path,
    sep = "\t", quote = FALSE, row.names = FALSE
  )

  start <- proc.time()
  status <- system2(
    mageck,
    c(
      "mle",
      "-k", count_path,
      "-d", design_path,
      "-n", prefix,
      "--norm-method", "median",
      "--permutation-round", "1",
      "--no-permutation-by-group",
      "--threads", "4"
    ),
    env = mageck_environment
  )
  elapsed <- unname((proc.time() - start)[["elapsed"]])
  if (status != 0 || !file.exists(summary_path)) {
    stop("Official MAGeCK-MLE analysis failed for ", label, ".")
  }
  raw <- read.delim(summary_path, check.names = FALSE)
  result <- data.frame(
    gene = raw$Gene,
    n_guides = raw$sgRNA,
    estimate = raw[["phenotype|beta"]] / score_range,
    p_value = raw[["phenotype|wald-p-value"]],
    fdr = raw[["phenotype|wald-fdr"]]
  )
  write.csv(
    result,
    file.path(result_dir, paste0(label, "_gene_results.csv")),
    row.names = FALSE
  )
  write.csv(
    data.frame(
      method = label,
      elapsed_seconds = elapsed,
      genes_per_second = nrow(result) / elapsed
    ),
    file.path(result_dir, paste0(label, "_runtime.csv")),
    row.names = FALSE
  )
  result
}

mageck_three <- run_mageck_mle(
  "mageck_mle_low_bulk_high", three_sample_index
)
mageck_tails <- run_mageck_mle("mageck_mle_two_tails", tail_index)

auroc <- function(truth, score) {
  score_rank <- rank(score, ties.method = "average")
  n_positive <- sum(truth)
  n_negative <- sum(!truth)
  (
    sum(score_rank[truth]) -
      n_positive * (n_positive + 1) / 2
  ) / (n_positive * n_negative)
}

average_precision <- function(truth, score) {
  ordered_truth <- truth[order(score, decreasing = TRUE)]
  precision_at_rank <- cumsum(ordered_truth) / seq_along(ordered_truth)
  mean(precision_at_rank[ordered_truth])
}

evaluate <- function(method, gene_result, design) {
  assessed <- merge(
    gene_truth,
    gene_result[, c("gene", "estimate", "p_value", "fdr")],
    by = "gene",
    all.x = TRUE
  )
  assessed <- assessed[
    is.finite(assessed$estimate) &
      is.finite(assessed$p_value) &
      is.finite(assessed$fdr),
    ,
    drop = FALSE
  ]
  score <- -log10(pmax(assessed$p_value, .Machine$double.xmin))
  called <- assessed$fdr < 0.10
  sign_match <- sign(assessed$estimate) == assessed$expected_sign
  tp <- sum(called & assessed$active)
  fp <- sum(called & !assessed$active)
  fn <- sum(!called & assessed$active)
  precision <- if ((tp + fp) > 0) tp / (tp + fp) else 0
  recall <- tp / (tp + fn)
  f1 <- if ((precision + recall) > 0) {
    2 * precision * recall / (precision + recall)
  } else {
    0
  }
  active <- assessed$active
  negative_control <- assessed$class == "negcontrol"
  data.frame(
    method = method,
    design = design,
    genes = nrow(assessed),
    active_genes = sum(active),
    auroc = auroc(active, score),
    average_precision = average_precision(active, score),
    effect_spearman_active = cor(
      assessed$estimate[active],
      assessed$theoretical_phenotype[active],
      method = "spearman"
    ),
    direction_accuracy_active = mean(sign_match[active]),
    calls_fdr_0_10 = sum(called),
    directional_recall_fdr_0_10 =
      mean(called[active] & sign_match[active]),
    empirical_fdp_fdr_0_10 =
      if (sum(called) > 0) fp / sum(called) else 0,
    f1_fdr_0_10 = f1,
    negative_control_p_below_0_05 =
      mean(assessed$p_value[negative_control] < 0.05)
  )
}

metrics <- rbind(
  evaluate("BARCS", barcs_three, "Low + bulk + high"),
  evaluate("MAGeCK-MLE", mageck_three, "Low + bulk + high"),
  evaluate("BARCS", barcs_tails, "Two 25% tails"),
  evaluate("MAGeCK-MLE", mageck_tails, "Two 25% tails"),
  evaluate("Bulk vs input", barcs_bulk, "Unsorted 0-100%")
)
write.csv(
  metrics,
  file.path(result_dir, "benchmark_metrics.csv"),
  row.names = FALSE
)

all_results <- list(
  `BARCS / low + bulk + high` = barcs_three,
  `MAGeCK-MLE / low + bulk + high` = mageck_three,
  `BARCS / two tails` = barcs_tails,
  `MAGeCK-MLE / two tails` = mageck_tails,
  `Bulk vs input` = barcs_bulk
)
effect_table <- do.call(rbind, lapply(names(all_results), function(label) {
  result <- merge(
    gene_truth[, c("gene", "class", "active", "theoretical_phenotype")],
    all_results[[label]][, c("gene", "estimate", "p_value", "fdr")],
    by = "gene"
  )
  result$method <- label
  result
}))
write.csv(
  effect_table,
  file.path(result_dir, "gene_effects_with_truth.csv"),
  row.names = FALSE
)

# Focused three-panel figure: design, truth recovery, and the required null.
pdf(figure_path, width = 11, height = 4.2, useDingbats = FALSE)
layout(matrix(1:3, nrow = 1), widths = c(1.15, 1.15, 1))

par(mar = c(4.2, 4.2, 2.3, 0.8))
x <- seq(-3.5, 3.5, length.out = 800)
y <- dnorm(x)
plot(
  x, y, type = "n", xlab = "Latent FACS phenotype (z)",
  ylab = "Cell density", yaxt = "n", bty = "l",
  main = "A  Sorting design"
)
regions <- list(c(-3.5, q25), c(-q25, 3.5))
fills <- c("#56B4E980", "#D55E0080")
for (index in seq_along(regions)) {
  keep <- x >= regions[[index]][1L] & x <= regions[[index]][2L]
  polygon(
    c(x[keep], rev(x[keep])),
    c(y[keep], rep(0, sum(keep))),
    col = fills[index], border = NA
  )
}
lines(x, y, lwd = 1.5)
abline(v = c(q25, -q25), lty = 3, col = "#555555")
text(
  c(-1.45, 1.45), c(0.07, 0.07),
  c("Low\n25%", "High\n25%"),
  cex = 0.82
)
arrows(-3.25, 0.31, 3.25, 0.31, code = 3, length = 0.05)
text(0, 0.335, "Bulk 0-100% (overlapping)", cex = 0.76)

performance <- metrics[metrics$method != "Bulk vs input", ]
metric_matrix <- rbind(
  AUROC = performance$auroc,
  `Average precision` = performance$average_precision,
  `Directional recall` = performance$directional_recall_fdr_0_10
)
method_labels <- paste(performance$method, performance$design, sep = "\n")
method_colours <- ifelse(
  performance$method == "BARCS",
  barcs_method_colours[["BARCS"]],
  barcs_method_colours[["MAGeCK"]]
)
par(mar = c(7.2, 4.2, 2.3, 0.8))
positions <- barplot(
  metric_matrix,
  beside = TRUE,
  col = rep(method_colours, each = nrow(metric_matrix)),
  density = rep(c(-1, 18, 35), times = ncol(metric_matrix)),
  angle = 45,
  border = method_colours,
  ylim = c(0, 1),
  ylab = "Truth-recovery metric",
  names.arg = method_labels,
  las = 2,
  cex.names = 0.67,
  main = "B  Sorted-bin recovery"
)
abline(h = 0.5, lty = 3, col = "#777777")
legend(
  "bottomright",
  legend = rownames(metric_matrix),
  fill = rep("#555555", 3L),
  border = "#333333",
  density = c(-1, 18, 35),
  angle = 45,
  cex = 0.68,
  bty = "n"
)

bulk_effect <- merge(
  gene_truth,
  barcs_bulk[, c("gene", "estimate", "p_value")],
  by = "gene"
)
par(mar = c(4.2, 4.2, 2.3, 0.8))
plot(
  bulk_effect$theoretical_phenotype,
  bulk_effect$estimate,
  pch = 16,
  cex = 0.55,
  col = ifelse(
    bulk_effect$active,
    paste0(barcs_method_colours[["BARCS"]], "99"),
    "#99999966"
  ),
  xlab = "True guide-aggregated phenotype",
  ylab = "Bulk-vs-input estimate",
  main = "C  Unsorted null reference",
  bty = "l"
)
abline(h = 0, lty = 2, col = "#555555")
legend(
  "topright",
  legend = sprintf(
    "AUROC = %.2f\nSpearman = %.2f",
    metrics$auroc[metrics$method == "Bulk vs input"],
    cor(
      bulk_effect$theoretical_phenotype,
      bulk_effect$estimate,
      method = "spearman"
    )
  ),
  bty = "n",
  cex = 0.8
)
dev.off()

print(metrics)
